import { z } from "zod";

/*
 * WP95 (docs/lab/beta-spec.md): the shape of the "Spot the fake" quiz
 * manifest, public/lab/spot-the-fake/quiz.json, generated by
 * tools/lab-spot-the-fake/generate.cjs. The page fetches the manifest at
 * runtime (a static file the Worker serves as-is; no lab data is ever in a
 * database) and refuses to render anything from it that does not validate —
 * the file names in particular are locked to [a-z0-9-]+\.webp so no entry
 * can ever point outside the tool's own public folder.
 *
 * Per round: file (the WebP under public/lab/spot-the-fake/), answer
 * ("real" or "ai"), a scene string used as the image's alt text, the one
 * tell sentence in English and Hindi, and the image's source/licence.
 */

export const SPOT_THE_FAKE_MANIFEST_URL = "/lab/spot-the-fake/quiz.json";

/** The spec's per-image cap; enforced by the generator and the unit test. */
export const SPOT_THE_FAKE_MAX_IMAGE_BYTES = 150 * 1024;

const localizedText = z.string().trim().min(1);

export const quizRoundSchema = z.strictObject({
  file: z.string().regex(/^[a-z0-9][a-z0-9-]*\.webp$/, "a WebP file name inside public/lab/spot-the-fake"),
  answer: z.enum(["real", "ai"]),
  scene: z.strictObject({ en: localizedText, hi: localizedText }),
  tell: z.strictObject({ en: localizedText, hi: localizedText }),
  source: localizedText,
});

export const quizManifestSchema = z.strictObject({
  version: z.literal(1),
  rounds: z.array(quizRoundSchema).min(1),
});

export type QuizRound = z.infer<typeof quizRoundSchema>;
export type QuizManifest = z.infer<typeof quizManifestSchema>;
export type QuizAnswer = QuizRound["answer"];

/** The manifest URL the client fetches, kept here so tests share it. */
export function quizImageUrl(file: string) {
  return `/lab/spot-the-fake/${file}`;
}
